const data = require('fs').readFileSync('/dev/stdin', 'utf8').split(/\s+/).filter(x => x.length > 0).map(Number);
let idx = 0;

const mod = 1000000007n;

function make3D(x, y, z) {
    const arr = new Array(x);
    for (let i = 0; i < x; i++) {
        arr[i] = new Array(y);
        for (let j = 0; j < y; j++) {
            arr[i][j] = new Array(z).fill(0n);
        }
    }
    return arr;
}

function make2D(x, y) {
    const arr = new Array(x);
    for (let i = 0; i < x; i++) {
        arr[i] = new Array(y).fill(0n);
    }
    return arr;
}

const dp = make3D(55, 55, 205);
const c = make2D(55, 55);

const n = data[idx++];
const lim = data[idx++];
let A = 0, B = 0;

for (let i = 0; i < n; i++) {
    const fk = data[idx++];
    if (fk === 50) A++;
    else B++;
}

dp[A][B][0] = 1n;
c[0][0] = 1n;

for (let i = 1; i <= 50; i++) {
    for (let j = 0; j <= i; j++) {
        if (j - 1 >= 0) {
            c[i][j] = (c[i - 1][j - 1] + c[i - 1][j]) % mod;
        } else {
            c[i][j] = c[i - 1][j] % mod;
        }
    }
}

let found = false;

for (let k = 1; k <= 4 * n && !found; k++) {
    for (let i = A; i >= 0 && !found; i--) {
        for (let j = B; j >= 0 && !found; j--) {
            const s = k % 2;
            dp[i][j][k] = 0n;
            if (s) {
                for (let ii = i; ii <= A; ii++) {
                    let f = lim - (ii - i) * 50;
                    if (f >= 0) {
                        f = Math.floor(f / 100);
                        f += j;
                        f = Math.min(f, B);
                        for (let jj = j; jj <= f; jj++) {
                            if (i !== ii || j !== jj) {
                                dp[i][j][k] = (dp[i][j][k] + (dp[ii][jj][k - 1] * c[ii][ii - i] * c[jj][jj - j]) % mod) % mod;
                            }
                        }
                    }
                }
            } else {
                for (let ii = 0; ii <= i; ii++) {
                    let f = lim - (i - ii) * 50;
                    if (f >= 0) {
                        f = Math.floor(f / 100);
                        f = Math.max(j - f, 0);
                        for (let jj = f; jj <= j; jj++) {
                            if (i !== ii || j !== jj) {
                                dp[i][j][k] = (dp[i][j][k] + (dp[ii][jj][k - 1] * c[A - ii][i - ii] * c[B - jj][j - jj]) % mod) % mod;
                            }
                        }
                    }
                }
            }
            if (dp[0][0][k] !== 0n) {
                console.log(k);
                console.log(dp[0][0][k].toString());
                found = true;
            }
        }
    }
}

if (!found) {
    console.log("-1");
    console.log("0");
}
